using AnaliticAsd.Domain.Dashboards;using Microsoft.EntityFrameworkCore;using Microsoft.EntityFrameworkCore.Metadata.Builders;
namespace AnaliticAsd.Infrastructure.Persistence.Configurations;
internal sealed class BrandProfileConfiguration:IEntityTypeConfiguration<BrandProfile>{public void Configure(EntityTypeBuilder<BrandProfile>b){b.ToTable("brand_profiles");b.HasKey(x=>x.Id);b.Property(x=>x.Id).HasColumnName("id");b.Property(x=>x.AgencyId).HasColumnName("agency_id");b.Property(x=>x.ClientId).HasColumnName("client_id");b.Property(x=>x.LogoUrl).HasColumnName("logo_url").HasMaxLength(2048);b.Property(x=>x.PrimaryColor).HasColumnName("primary_color").HasMaxLength(7);b.Property(x=>x.SecondaryColor).HasColumnName("secondary_color").HasMaxLength(7);b.Property(x=>x.BackgroundColor).HasColumnName("background_color").HasMaxLength(7);b.Property(x=>x.FontFamily).HasColumnName("font_family").HasMaxLength(100);b.Property(x=>x.UpdatedAtUtc).HasColumnName("updated_at_utc");b.Property(x=>x.Version).HasColumnName("version").IsConcurrencyToken();b.HasIndex(x=>new{x.AgencyId,x.ClientId}).IsUnique().HasFilter("client_id IS NOT NULL");b.HasIndex(x=>x.AgencyId).IsUnique().HasFilter("client_id IS NULL");}}
